//! Byte-for-byte comparison with npm autobee 2.12.1, generated by
//! `fixtures/gen/encryption.mjs`.

use serde_json::Value;

use autobee::encryption::{
    AutobeeEncryption, DEFAULT_MANIFEST_VERSION, Error, ManifestContext, PADDING,
};
use autobee::order_hash;

const FIXTURES: &str = include_str!("../fixtures/encryption-reference.json");

fn fixtures() -> Value {
    serde_json::from_str(FIXTURES).expect("valid fixture json")
}

fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex length: {s:?}");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digits"))
        .collect()
}

fn hex32(value: &Value, name: &str) -> [u8; 32] {
    unhex(value[name].as_str().expect("hex string"))
        .try_into()
        .expect("32 bytes")
}

fn provider(case: &Value) -> AutobeeEncryption {
    let bootstrap = hex32(case, "bootstrap");
    let encryption_key = hex32(case, "encryption_key");
    let manifest = ManifestContext {
        version: case["manifest_version"].as_u64().expect("manifest version"),
        key: hex32(case, "core_key"),
        user_data: case["user_data"]
            .as_str()
            .map(unhex)
            .filter(|u| !u.is_empty()),
    };

    if case["core"] == "writer" {
        AutobeeEncryption::writer(bootstrap, encryption_key, manifest)
    } else {
        AutobeeEncryption::view(bootstrap, encryption_key, case["name"].as_str(), manifest)
    }
}

fn label(case: &Value, i: usize) -> String {
    format!(
        "{i}: {} {:?} manifest {} index {}",
        case["core"].as_str().unwrap_or("?"),
        case["name"],
        case["manifest_version"],
        case["index"]
    )
}

#[test]
fn constants_match() {
    let f = fixtures();
    assert_eq!(f["constants"]["padding"].as_u64(), Some(PADDING as u64));
    assert_eq!(
        f["constants"]["default_manifest_version"].as_u64(),
        Some(DEFAULT_MANIFEST_VERSION)
    );
}

#[test]
fn encryption_matches_js() {
    let f = fixtures();
    let cases = f["cases"].as_array().expect("cases array");
    assert!(cases.len() >= 100, "only {} cases", cases.len());

    let mut encrypted = 0;
    for (i, case) in cases.iter().enumerate() {
        let name = label(case, i);
        let enc = provider(case);
        let index = case["index"].as_u64().expect("index");
        let fork = case["fork"].as_u64().expect("fork");
        let block = unhex(case["block"].as_str().expect("block"));
        let plaintext = unhex(case["expected"].as_str().expect("expected"));
        let mode = case["mode"].as_str().expect("mode");

        let mut ciphertext = match mode {
            "encrypt" => {
                let want = unhex(case["encrypted"].as_str().expect("encrypted"));
                let mut buf = block.clone();
                enc.encrypt(index, &mut buf, fork).expect("encrypt");
                assert_eq!(buf, want, "encrypt case {name}");
                encrypted += 1;
                want
            }
            "decrypt-only" => {
                assert_eq!(
                    enc.encrypt(index, &mut block.clone(), fork),
                    Err(Error::UnsupportedManifestVersion),
                    "compat view must refuse to encrypt, case {name}"
                );
                block.clone()
            }
            "plaintext" => block.clone(),
            other => panic!("unknown mode {other} in case {name}"),
        };

        enc.decrypt(index, &mut ciphertext).expect("decrypt");
        assert_eq!(
            &ciphertext[PADDING..],
            plaintext.as_slice(),
            "decrypt case {name}"
        );
    }

    assert!(encrypted >= 100, "only {encrypted} encrypt vectors");
}

#[test]
fn anchors_match_js() {
    let f = fixtures();
    let anchors = f["anchors"].as_array().expect("anchors array");
    assert!(!anchors.is_empty());

    for (i, anchor) in anchors.iter().enumerate() {
        let mut block = unhex(anchor["block"].as_str().expect("block"));
        AutobeeEncryption::encrypt_anchor(
            &mut block,
            &hex32(anchor, "bootstrap"),
            &hex32(anchor, "encryption_key"),
            &hex32(anchor, "namespace"),
        )
        .expect("encrypt anchor");
        assert_eq!(
            block,
            unhex(anchor["encrypted"].as_str().expect("encrypted")),
            "anchor {i}"
        );
        assert_eq!(
            &block[PADDING..].len(),
            &unhex(anchor["plaintext"].as_str().expect("plaintext")).len()
        );
    }
}

#[test]
fn order_hash_matches_js() {
    let f = fixtures();
    let hashes = f["order_hash"].as_array().expect("order_hash array");
    assert!(hashes.len() >= 50, "only {} order hashes", hashes.len());

    for (i, case) in hashes.iter().enumerate() {
        let prev: Option<[u8; order_hash::HASHBYTES]> = case["prev"]
            .as_str()
            .map(|h| unhex(h).try_into().expect("8 bytes"));
        let hash = order_hash::advance_hash(
            prev.as_ref(),
            &hex32(case, "key"),
            case["length"].as_u64().expect("length"),
            case["weight"].as_u64().expect("weight"),
        );
        assert_eq!(
            hash.to_vec(),
            unhex(case["hash"].as_str().expect("hash")),
            "order hash {i}"
        );
    }
}

#[test]
fn rejects_unknown_type_byte() {
    let case = serde_json::json!({
        "core": "view",
        "name": null,
        "bootstrap": "00".repeat(32),
        "encryption_key": "11".repeat(32),
        "manifest_version": 3,
        "core_key": "22".repeat(32),
        "user_data": null,
        "index": 0,
        "fork": 0
    });
    let enc = provider(&case);
    let mut block = vec![2u8; PADDING + 4];
    assert_eq!(
        enc.decrypt(0, &mut block),
        Err(Error::UnrecognisedEncryptionType(2))
    );
    assert_eq!(
        enc.decrypt(0, &mut [0u8; PADDING - 1]),
        Err(Error::BlockTooShort)
    );
}
